------------ define ------------
local AnimationName = "JumpImageNode"
------------ define ------------

--- from: Assets/BundleResources/Prefabs/UIBattling/JumpImagePrewarNode.prefab
---@class JumpPassiveIconNode
---@field Env                           	JumpPassiveIconNode                     
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Animation_FxGlow              	UnityEngine.Animation                   
---@field Switch_Icon                   	Game.Native.Common.UISwitchImage        
---@field Root_Animator                 	UnityEngine.Animation                   
---@field Switch_Desc                   	Game.Native.Common.UISwitchText         
---@field Txt_Desc                      	UnityEngine.UI.Text                            
local JumpPassiveIconNode = Class('JumpPassiveIconNode')

------------ LifeCycle ------------

function JumpPassiveIconNode:__init()
    self:CleanProperty()
end

function JumpPassiveIconNode:__delete()
    self:CleanProperty()
end

function JumpPassiveIconNode:CleanProperty()
    self.coShow = nil
end

function JumpPassiveIconNode:Awake()
end

function JumpPassiveIconNode:Start()
end

function JumpPassiveIconNode:OnDestroy()
    if self.coShow then
        cs_coroutine.stop(self.coShow)
        self.coShow = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

------------ LifeCycle ------------

---ShowValue
---@param type integer 被动来源类型
function JumpPassiveIconNode:ShowValue(type, offset)
    if not isNull(offset) then
        self.controller.transform.anchoredPosition = offset
    end
    self.coShow = cs_coroutine.start(function()
        xTry(function()
            self.Switch_Icon.Status = Constants.PassiveBuffTypeToSwitchId[type]
            self.Switch_Desc.Status = Constants.PassiveBuffTypeToSwitchId[type]
            self.Txt_Desc.text = UIBattlingDataMgr:GetBattleTipsData(Constants.PassiveBuffDescMap[type])
            local glowAnimName = Constants.PassiveBuffGlowAnimation[type]
            if isNotNull(glowAnimName) then
                self.Animation_FxGlow:Play(glowAnimName)
            end
            cs_coroutine.yield_return(self:PlayJumpNodeAnimation(AnimationName))
            self.coShow = nil
        end)
    end)
end

function JumpPassiveIconNode:PlayJumpNodeAnimation(animPath, cb)
    if not IsNull(self.Root_Animator) and animPath then
        self.Root_Animator:Play(animPath)
        while self.Root_Animator.isPlaying do
            cs_coroutine.yield_return()
        end
        if cb then cb() end
        cs_coroutine.yield_return()
    end
    UIBattlingTools.RecyclePoolObj(self.controller.gameObject, true)
end

return JumpPassiveIconNode